// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Delete(options.BaseURL+"/v1/connection", wrapper.DisconnectGoogle)

	router.Get(options.BaseURL+"/v1/connection", wrapper.GetGoogleConnection)

	router.Patch(options.BaseURL+"/v1/connection", wrapper.UpdateGoogleConnection)

	router.Post(options.BaseURL+"/v1/connection", wrapper.ConnectGoogle)

	router.Post(options.BaseURL+"/v1/connection/authorize", wrapper.AuthorizeGoogle)

	router.Get(options.BaseURL+"/v1/calendars", wrapper.ListGoogleCalendars)

	router.Post(options.BaseURL+"/v1/calendars/refresh", wrapper.RefreshGoogleCalendars)

	router.Patch(options.BaseURL+"/v1/calendars/:calendarId", wrapper.UpdateGoogleCalendar)

	router.Post(options.BaseURL+"/v1/calendars/:calendarId/sync", wrapper.SyncGoogleCalendar)

	router.Get(options.BaseURL+"/v1/exports", wrapper.ListEventExports)

}
